import React, { useState, useRef } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import axios from "axios";
import { useAuth } from "../context/AuthContext";

const GRADS = ["rt1","rt2","rt3","rt4","rt5","rt6"];

const UploadArea = ({ label, inputRef, fileName, setFileName, onFile }) => (
  <div>
    <label style={{ fontSize: 12, fontWeight: 600, display: "block", marginBottom: 8 }}>{label} <span style={{ color: "var(--coral)" }}>*</span></label>
    <div style={{ border: "2px dashed var(--border)", borderRadius: "var(--r-md)", padding: 28, textAlign: "center", background: "var(--cream)", cursor: "pointer", transition: "border-color .15s" }}
      onClick={() => inputRef.current?.click()}
      onMouseEnter={e => e.currentTarget.style.borderColor = "var(--gold)"}
      onMouseLeave={e => e.currentTarget.style.borderColor = "var(--border)"}>
      <div style={{ fontSize: 30, marginBottom: 10 }}>🪪</div>
      {fileName ? (
        <p style={{ fontSize: 13, color: "var(--charcoal)", fontWeight: 500 }}>{fileName}</p>
      ) : (
        <>
          <p style={{ fontSize: 13, color: "var(--muted)" }}>Drag & drop or <span style={{ color: "var(--gold)", fontWeight: 600 }}>Browse file</span></p>
          <p style={{ fontSize: 11, marginTop: 6, color: "var(--muted)" }}>JPG, PNG or PDF · Max 5 MB</p>
        </>
      )}
    </div>
    <input ref={inputRef} type="file" accept=".jpg,.jpeg,.png,.pdf" hidden onChange={e => {
      const file = e.target.files?.[0];
      setFileName(file?.name || "");
      if (file && onFile) {
        const reader = new FileReader();
        reader.onload = () => onFile(reader.result);
        reader.readAsDataURL(file);
      }
    }} />
  </div>
);

export default function BookingPage() {
  const { state } = useLocation();
  const navigate  = useNavigate();
  const { user }  = useAuth();

  const room   = state?.room;
  const dates  = state?.dates  || {};
  const nights = state?.nights || 0;
  const total  = state?.total  || 0;
  const guests = state?.guests || 1;

  const [step, setStep] = useState(1);
  const [agreed, setAgreed] = useState(false);
  const [loading, setLoading] = useState(false);
  const [msg, setMsg] = useState("");

  const idFrontRef = useRef(null);
  const idBackRef = useRef(null);
  const [idFrontName, setIdFrontName] = useState("");
  const [idBackName, setIdBackName] = useState("");


  const [form, setForm] = useState({
    firstName:  user?.first_name || "",
    lastName:   user?.last_name  || "",
    email:      user?.email      || "",
    phone:      user?.phone      || "",
    special:    "",
    cardName:   "",
    cardNumber: "",
    cardExpiry: "",
    cardCvv:    "",
  });

  if (!room) return (
    <div style={{ padding: 80, textAlign: "center" }}>
      <p style={{ color: "var(--muted)" }}>No booking info. <span style={{ color: "var(--gold)", cursor: "pointer" }} onClick={() => navigate("/explore")}>Go explore rooms</span>.</p>
    </div>
  );

  const grad = GRADS[0];
  const thumb = room.images?.[0] || `https://picsum.photos/seed/roomly-${room._id || "book"}-thumb/200/160`;

  const handleConfirm = async () => {
    if (!agreed) { setMsg("Please agree to the terms."); return; }
    if (!idFrontName) { setMsg("Please upload the front side of your national ID."); return; }
    if (!idBackName) { setMsg("Please upload the back side of your national ID."); return; }
    if (!form.cardName) { setMsg("Please enter the cardholder name."); return; }
    if (!form.cardNumber) { setMsg("Please enter the card number."); return; }
    if (!/^\d+$/.test(form.cardNumber)) { setMsg("Card number must contain only digits."); return; }
    if (!form.cardExpiry) { setMsg("Please enter the card expiry date."); return; }
    if (form.cardCvv.length !== 3) { setMsg("CVV must be 3 digits."); return; }
    setLoading(true); setMsg("");
    try {
      const fd = new FormData();
      if (idFrontRef.current?.files?.[0]) fd.append("front", idFrontRef.current.files[0]);
      if (idBackRef.current?.files?.[0])  fd.append("back",  idBackRef.current.files[0]);
      await axios.post("/api/documents/upload", fd);

      await axios.post("/api/bookings", {
        roomId:    room._id,
        startDate: dates.startDate,
        endDate:   dates.endDate,
      });
      navigate("/dashboard");
    } catch (err) {
      setMsg(err.response?.data?.message || "Booking failed. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const SectionNum = ({ n }) => (
    <span style={{ width: 26, height: 26, background: "var(--gold)", color: "white", borderRadius: "50%", display: "inline-flex", alignItems: "center", justifyContent: "center", fontSize: 12, fontWeight: 700, flexShrink: 0, marginRight: 10 }}>{n}</span>
  );

  const UploadArea = ({ label, inputRef, fileName, setFileName, onFile }) => (
    <div>
      <label style={{ fontSize: 12, fontWeight: 600, display: "block", marginBottom: 8 }}>{label} <span style={{ color: "var(--coral)" }}>*</span></label>
      <div style={{ border: "2px dashed var(--border)", borderRadius: "var(--r-md)", padding: 28, textAlign: "center", background: "var(--cream)", cursor: "pointer", transition: "border-color .15s" }}
        onClick={() => inputRef.current?.click()}
        onMouseEnter={e => e.currentTarget.style.borderColor = "var(--gold)"}
        onMouseLeave={e => e.currentTarget.style.borderColor = "var(--border)"}>
        <div style={{ fontSize: 30, marginBottom: 10 }}>🪪</div>
        {fileName ? (
          <p style={{ fontSize: 13, color: "var(--charcoal)", fontWeight: 500 }}>{fileName}</p>
        ) : (
          <>
            <p style={{ fontSize: 13, color: "var(--muted)" }}>Drag & drop or <span style={{ color: "var(--gold)", fontWeight: 600 }}>Browse file</span></p>
            <p style={{ fontSize: 11, marginTop: 6, color: "var(--muted)" }}>JPG, PNG or PDF · Max 5 MB</p>
          </>
        )}
      </div>
      <input ref={inputRef} type="file" accept=".jpg,.jpeg,.png,.pdf" hidden onChange={e => {
        const file = e.target.files?.[0];
        setFileName(file?.name || "");
        if (file && onFile) {
          const reader = new FileReader();
          reader.onload = () => onFile(reader.result);
          reader.readAsDataURL(file);
        }
      }} />
    </div>
  );

  return (
    <div style={{ maxWidth: 780, margin: "0 auto", padding: "48px 40px" }}>
      <span className="sec-label">Secure Booking</span>
      <h2 className="h2" style={{ marginBottom: 6 }}>Complete your reservation</h2>
      <p style={{ fontSize: 14, color: "var(--muted)", marginBottom: 32 }}>All bookings require identity verification to keep hosts and guests safe.</p>

      {/* Trip Summary */}
      <div style={{ background: "white", border: "1px solid var(--border)", borderRadius: "var(--r-lg)", padding: 28, marginBottom: 20 }}>
        <h3 style={{ fontSize: 16, fontWeight: 600, marginBottom: 20, display: "flex", alignItems: "center" }}>
          <span style={{ width: 26, height: 26, background: "var(--teal)", color: "white", borderRadius: "50%", display: "inline-flex", alignItems: "center", justifyContent: "center", fontSize: 12, marginRight: 10 }}>✓</span>
          Your trip
        </h3>
        <div style={{ display: "flex", gap: 16, alignItems: "center" }}>
          <div
            className={grad}
            style={{
              width: 90,
              height: 72,
              borderRadius: 10,
              flexShrink: 0,
              backgroundImage: `url(${thumb})`,
              backgroundSize: "cover",
              backgroundPosition: "center",
              filter: "blur(3px)",
              boxShadow: "inset 0 0 20px rgba(0, 0, 0, 0.2)",
            }}
          />
          <div>
            <div style={{ fontWeight: 600, fontSize: 15, marginBottom: 3 }}>{room.title || room.description?.substring(0,40) || room.type}</div>
            <div style={{ fontSize: 13, color: "var(--muted)" }}>📍 {room.location}, {room.city} · {room.type}</div>
            <div style={{ fontSize: 13, color: "var(--muted)" }}>📅 {dates.startDate} – {dates.endDate} · {nights} nights · {guests} guest{guests > 1 ? "s" : ""}</div>
          </div>
          <div style={{ marginLeft: "auto", textAlign: "right" }}>
            <div style={{ fontFamily: "'DM Serif Display',serif", fontSize: 20 }}>${total}</div>
            <div style={{ fontSize: 11, color: "var(--muted)" }}>total incl. fees</div>
            {room.discountRate > 0 && <div style={{ fontSize: 11, color: "var(--coral)", fontWeight: 600 }}>{room.discountRate}% discount applied</div>}
          </div>
        </div>
        <div style={{ background: "var(--cream)", border: "1px solid var(--border)", borderRadius: "var(--r-md)", padding: 16, marginTop: 14 }}>
          {[
            [`$${Math.round(room.pricePerNight * (1 - room.discountRate/100))} × ${nights} nights`, `$${Math.round(room.pricePerNight * (1 - room.discountRate/100)) * nights}`],
            ["Cleaning fee", "$25"],
            ["Roomly service fee", "$43"],
          ].map(([l, v]) => (
            <div key={l} style={{ display: "flex", justifyContent: "space-between", fontSize: 13, marginBottom: 8, color: "var(--muted)" }}>
              <span>{l}</span><span>{v}</span>
            </div>
          ))}
          <div style={{ display: "flex", justifyContent: "space-between", fontWeight: 600, color: "var(--charcoal)", fontSize: 15, borderTop: "1px solid var(--border)", paddingTop: 10, marginTop: 4 }}>
            <span>Total (USD)</span><span>${total}</span>
          </div>
        </div>
      </div>

      {/* Step 1 — Guest Info */}
      <div style={{ background: "white", border: "1px solid var(--border)", borderRadius: "var(--r-lg)", padding: 28, marginBottom: 20 }}>
        <h3 style={{ fontSize: 16, fontWeight: 600, marginBottom: 20, display: "flex", alignItems: "center" }}>
          <SectionNum n="1" />Guest information
        </h3>
        <div className="form-row">
          {[["First name","firstName","Mostafa"],["Last name","lastName","Ali"]].map(([lbl,key,ph]) => (
            <div key={key} className="form-group">
              <label>{lbl}</label>
              <input type="text" className="form-input" placeholder={ph} value={form[key]} disabled />
            </div>
          ))}
        </div>
        <div className="form-row">
          <div className="form-group">
            <label>Email address</label>
            <div className="inp-icon-wrap"><span className="inp-icon">✉️</span>
              <input type="email" className="form-input" placeholder="you@example.com" value={form.email} disabled />
            </div>
          </div>
          <div className="form-group">
            <label>Phone number</label>
            <div className="inp-icon-wrap"><span className="inp-icon">📱</span>
              <input type="tel" className="form-input" placeholder="+20 100 000 0000" value={form.phone} disabled />
            </div>
          </div>
        </div>
        <div className="form-group">
          <label>Special requests <span style={{ color: "var(--muted)", fontWeight: 400 }}>(optional)</span></label>
          <textarea className="form-input" rows={2} placeholder="Early check-in, quiet floor, etc." style={{ resize: "vertical" }} value={form.special} onChange={e => setForm(p => ({...p,special:e.target.value}))} />
        </div>
      </div>

      {/* Step 2 — ID Verification */}
      <div style={{ background: "white", border: "1px solid var(--border)", borderRadius: "var(--r-lg)", padding: 28, marginBottom: 20 }}>
        <h3 style={{ fontSize: 16, fontWeight: 600, marginBottom: 20, display: "flex", alignItems: "center" }}>
          <SectionNum n="2" />Identity verification
        </h3>
        <p style={{ fontSize: 14, color: "var(--muted)", marginBottom: 18 }}>Roomly requires a valid national ID for all bookings. This protects both hosts and guests and is kept securely encrypted.</p>
        <UploadArea label="National ID — Front side" inputRef={idFrontRef} fileName={idFrontName} setFileName={setIdFrontName} />
        <div style={{ marginTop: 14 }}>
          <UploadArea label="National ID — Back side" inputRef={idBackRef} fileName={idBackName} setFileName={setIdBackName} />
        </div>
        <div style={{ display: "flex", gap: 10, alignItems: "flex-start", background: "var(--gold-lt)", border: "1px solid rgba(200,151,90,.3)", borderRadius: "var(--r-sm)", padding: 12, marginTop: 12, fontSize: 13, color: "var(--gold-dk)" }}>
          <span style={{ fontSize: 18 }}>🔒</span>
          <div>Your national ID is encrypted using AES-256 and only accessible to Roomly's trust & safety team. It will never be shared with hosts or third parties.</div>
        </div>
      </div>

      {/* Step 3 — Payment */}
      <div style={{ background: "white", border: "1px solid var(--border)", borderRadius: "var(--r-lg)", padding: 28, marginBottom: 20 }}>
        <h3 style={{ fontSize: 16, fontWeight: 600, marginBottom: 20, display: "flex", alignItems: "center" }}>
          <SectionNum n="3" />Payment
        </h3>
        <p style={{ fontSize: 13, color: "var(--muted)", marginBottom: 16 }}>You won't be charged until your booking is confirmed by the host.</p>
        <div className="form-group">
          <label>Cardholder name</label>
          <input type="text" className="form-input" placeholder="Name on card" value={form.cardName} onChange={e => setForm(p => ({...p, cardName: e.target.value}))} />
        </div>
        <div className="form-group">
          <label>Card number</label>
          <div className="inp-icon-wrap"><span className="inp-icon">💳</span>
            <input type="text" inputMode="numeric" className="form-input" placeholder="1234 5678 9012 3456" value={form.cardNumber} onChange={e => setForm(p => ({...p, cardNumber: e.target.value.replace(/\D/g, "").slice(0, 16)}))} />
          </div>
        </div>
        <div className="form-row">
          <div className="form-group"><label>Expiry</label><input type="text" inputMode="numeric" className="form-input" placeholder="MM / YY" value={form.cardExpiry} onChange={e => setForm(p => ({...p, cardExpiry: e.target.value.replace(/[^\d/]/g, "").slice(0, 5)}))} /></div>
          <div className="form-group"><label>CVV</label><input type="text" inputMode="numeric" className="form-input" placeholder="123" value={form.cardCvv} onChange={e => setForm(p => ({...p, cardCvv: e.target.value.replace(/\D/g, "").slice(0, 3)}))} /></div>
        </div>
        <div style={{ display: "flex", gap: 8, marginTop: 4 }}>
          {["💳 Visa","💳 Mastercard","💳 Mada","🏦 Bank Transfer"].map(p => (
            <div key={p} style={{ background: "var(--tag)", borderRadius: 6, padding: "6px 12px", fontSize: 12, color: "var(--muted)" }}>{p}</div>
          ))}
        </div>
      </div>

      {/* Agreement */}
      <div style={{ display: "flex", gap: 10, alignItems: "flex-start", marginBottom: 24, fontSize: 13, color: "var(--muted)" }}>
        <input type="checkbox" checked={agreed} onChange={e => setAgreed(e.target.checked)} style={{ marginTop: 3, accentColor: "var(--gold)" }} />
        <span>I confirm my information is accurate and agree to Roomly's <a href="#" style={{ color: "var(--gold)" }}>Terms</a> and <a href="#" style={{ color: "var(--gold)" }}>Privacy Policy</a>.</span>
      </div>

      {msg && <p style={{ color: "var(--coral)", fontSize: 13, marginBottom: 14 }}>{msg}</p>}

      <div style={{ display: "flex", gap: 12 }}>
        <button className="btn btn-out" onClick={() => navigate(-1)}>← Back</button>
        <button className="btn btn-gold" onClick={handleConfirm} disabled={loading} style={{ flex: 1, justifyContent: "center", padding: 14, fontSize: 15 }}>
          {loading ? "Confirming…" : `🔒 Confirm Booking · $${total}`}
        </button>
      </div>
    </div>
  );
}
